-- The Skyborne (mod-skyborne): generated by tools/build_data.py from the game's own tables;
-- edit that, not this. Safe to run again: every row is replaced, every mask OR'd.

-- The two races, on the blood elf's body.

-- Their looks (and the blood elf's Dark Ranger skin); the creatures' races 13 and 14 moved to 22 and 23.
DELETE FROM `charsections_dbc` WHERE `ID` BETWEEN 900000 AND 909999;


-- Their voices for the emotes.

-- Their classes' starting gear: the start race's for the class (or the nearest race's).

-- Skills and abilities open to either side's races are open to theirs (the racials and languages aside).
ON DUPLICATE KEY UPDATE `RaceMask` = `RaceMask` | VALUES(`RaceMask`);
UPDATE `skillraceclassinfo_dbc` SET `RaceMask` = `RaceMask` & ~12288 WHERE `ID` IN (41, 49) AND `RaceMask` > 0;
ON DUPLICATE KEY UPDATE `RaceMask` = `RaceMask` | VALUES(`RaceMask`);

-- Standing: the start race's (Stormwind's for the High Order, Thunder Bluff's for the Windshapers).

-- The intro: the start race's flight over its home, with the Skyborne's own narration.

-- Their racials: Walk on Air, Skysight (Windshapers, with Elemental Blessing), Read Ley Line (High Order,
-- with Energized), Wind Blessed, Elemental Insight.

-- Where they start (their start race's place), for every class.

-- Their action bars: the class's start race's, without that race's racials.
DELETE FROM `playercreateinfo_action` WHERE `race` IN (13, 14);

-- Their skills: their side's weapons and armour; Common or Orcish; no other race's racials.
UPDATE `playercreateinfo_skills` SET `raceMask` = `raceMask` | 12288 WHERE (`raceMask` & 2047) = 36 AND `classMask` = 4 AND `skill` = 46;
UPDATE `playercreateinfo_skills` SET `raceMask` = `raceMask` | 12288 WHERE (`raceMask` & 2047) = 650 AND `classMask` = 4 AND `skill` = 45;
UPDATE `playercreateinfo_skills` SET `raceMask` = `raceMask` | 8192 WHERE (`raceMask` & 2047) = 690 AND `classMask` = 0 AND `skill` = 109;
UPDATE `playercreateinfo_skills` SET `raceMask` = `raceMask` | 12288 WHERE (`raceMask` & 2047) = 735 AND `classMask` = 1293 AND `skill` = 173;
UPDATE `playercreateinfo_skills` SET `raceMask` = `raceMask` | 4096 WHERE (`raceMask` & 2047) = 1024 AND `classMask` = 4 AND `skill` = 226;
UPDATE `playercreateinfo_skills` SET `raceMask` = `raceMask` | 12288 WHERE (`raceMask` & 2047) = 1061 AND `classMask` = 3 AND `skill` = 160;
UPDATE `playercreateinfo_skills` SET `raceMask` = `raceMask` | 4096 WHERE (`raceMask` & 2047) = 1101 AND `classMask` = 0 AND `skill` = 98;

-- Their racials, learned at creation.
DELETE FROM `playercreateinfo_spell_custom` WHERE `Spell` BETWEEN 98701 AND 98707;

-- Their stats: WoW: Forever's starting stats for every class are the class's base with Strength -1,
-- Agility +1, Stamina -1, Intellect +1, Spirit 0. Druid forms: the night elf's. Totems: the tauren's.
DELETE FROM `player_shapeshift_model` WHERE `RaceID` IN (13, 14);
DELETE FROM `player_totem_model` WHERE `RaceID` IN (13, 14);

-- Quests, items and conditions for their start race are theirs too: the Humans' for the High Order,
-- the Tauren's for the Windshapers; and those of the race their classes' starts come from where the
-- start race hasn't the class (the Night Elves' hunters' and druids', the Blood Elves' rogues').
UPDATE `quest_template` SET `AllowableRaces` = `AllowableRaces` | 4096 WHERE `AllowableRaces` & 9 AND `AllowableRaces` & 0x7FFFFFFF <> 0x7FFFFFFF;
UPDATE `item_template` SET `AllowableRace` = `AllowableRace` | 4096 WHERE `AllowableRace` <> -1 AND `AllowableRace` & 9 AND `AllowableRace` & 0x7FFFFFFF <> 0x7FFFFFFF;
UPDATE `conditions` SET `ConditionValue1` = `ConditionValue1` | 4096 WHERE `ConditionTypeOrReference` = 16 AND `ConditionValue1` & 9;
UPDATE `quest_template` SET `AllowableRaces` = `AllowableRaces` | 8192 WHERE `AllowableRaces` & 544 AND `AllowableRaces` & 0x7FFFFFFF <> 0x7FFFFFFF;
UPDATE `item_template` SET `AllowableRace` = `AllowableRace` | 8192 WHERE `AllowableRace` <> -1 AND `AllowableRace` & 544 AND `AllowableRace` & 0x7FFFFFFF <> 0x7FFFFFFF;
UPDATE `conditions` SET `ConditionValue1` = `ConditionValue1` | 8192 WHERE `ConditionTypeOrReference` = 16 AND `ConditionValue1` & 544;
